### 4. Тестирование сервисов

**Тестирование простых сервисов:**
```typescript
// calculator.service.ts
@Injectable({
  providedIn: 'root'
})
export class CalculatorService {
  private history: string[] = [];
  
  add(a: number, b: number): number {
    const result = a + b;
    this.history.push(`${a} + ${b} = ${result}`);
    return result;
  }
  
  getHistory(): string[] {
    return [...this.history];
  }
  
  clearHistory(): void {
    this.history = [];
  }
}
```

**Тестирование сервиса:**
```typescript
// calculator.service.spec.ts
describe('CalculatorService', () => {
  let service: CalculatorService;
  
  beforeEach(() => {
    TestBed.configureTestingModule({});
    service = TestBed.inject(CalculatorService);
  });
  
  it('should be created', () => {
    expect(service).toBeTruthy();
  });
  
  describe('add method', () => {
    it('should add two numbers and store in history', () => {
      // Act
      const result = service.add(2, 3);
      
      // Assert
      expect(result).toBe(5);
      expect(service.getHistory()).toContain('2 + 3 = 5');
    });
    
    it('should handle multiple operations', () => {
      service.add(1, 1);
      service.add(5, 10);
      
      const history = service.getHistory();
      expect(history.length).toBe(2);
      expect(history).toContain('1 + 1 = 2');
      expect(history).toContain('5 + 10 = 15');
