  });

  it('should increment count', () => {
    component.increment();
    expect(component.count).toBe(1);
    
    fixture.detectChanges();
    expect(compiled.querySelector('h2')?.textContent).toContain('Счетчик: 1');
  });

  it('should decrement count', () => {
